INSERT INTO `wp_cartflows_ca_email_templates` VALUES
(3,'Modèle d\'e-mail 1','Votre panier vous attend - Profitez de 10% de remise !','<strong>Bonjour {{customer.fullname}},</strong>\r\n\r\nNous avons remarqué que vous avez laissé des articles dans votre panier :\r\n\r\n<strong>{{cart.product.names}}</strong>\r\n\r\nPour vous aider à finaliser votre commande, nous vous offrons <strong>10% de remise</strong> avec le code <strong>{{cart.coupon_code}}</strong> !\r\n\r\nC&#039;est une offre exclusive valable <strong>24 heures seulement</strong>.\r\n\r\n<strong>Ne manquez pas cette opportunité !</strong>\r\n\r\n[<strong>Finalisez Votre Achat Maintenant »</strong>]\r\n\r\nSi vous avez rencontré un problème technique ou si vous avez besoin d’aide, répondez simplement à cet e-mail. Notre équipe sera ravie de vous accompagner.\r\n\r\n<strong>Dépêchez-vous, cette offre est unique !</strong>\r\n\r\nCordialement,\r\n\r\n<strong>{{admin.firstname}}</strong>\r\n<strong>{{admin.company}}</strong>\r\n\r\n<hr />\r\n\r\n[Se désabonner de ces notifications] {{cart.unsubscribe}}',0,1,'DAY');
